import { chunks } from './chunks.js';
const $ = id => document.getElementById(id);
const stored = (key, fallback) => { try { return localStorage.getItem('lectoria_'+key) ?? fallback; } catch { return fallback; } };
// Preferences live in localStorage for speed and on the server per account (the server copy wins at sign-in).
const SYNCED=new Set(['voice','voice_pt-PT','voice_en-US','autoLang','engine','cacheBehind','cacheAhead','autoplayBuffer','prefetchMode','speed','volume','theme','mode','font','partialRecording','cloudCopy','syncEvery','autoHour','bookMode','bookPages','readContrast','readColors','readBg','readText','bookColors','uiReady','uiLocal','uiStripes','uiEta','uiWord','uiScroll','uiChapters','uiContrast','keepAwake']);
let pendingSync={},syncTimer;
const store = (key,value) => { try { localStorage.setItem('lectoria_'+key,String(value)); } catch {} if(SYNCED.has(key)&&state.user){pendingSync[key]=String(value);clearTimeout(syncTimer);syncTimer=setTimeout(()=>{const body=pendingSync;pendingSync={};api('settings',{method:'PUT',body:JSON.stringify(body)}).catch(()=>{});},800);} };
async function pullSettings(){try{const remote=await api('settings');for(const [key,value] of Object.entries(remote))if(SYNCED.has(key))localStorage.setItem('lectoria_'+key,value);if(!Object.keys(remote).length){const mine={};for(const key of SYNCED){const value=localStorage.getItem('lectoria_'+key);if(value!=null)mine[key]=value;}if(Object.keys(mine).length)api('settings',{method:'PUT',body:JSON.stringify(mine)}).catch(()=>{});}state.font=Number(stored('font',20));applyAppearance();if(typeof showSpeed==='function'){$('speed').value=stored('speed','1');if(!$('speed').value)$('speed').value='1';showSpeed();setVolume(stored('volume','80'),false);$('engine').value=stored('engine','host');engineHint();}}catch{}}
const state = { user:null, docs:[], doc:null, section:0, chunks:[], index:0, offset:0, position:0, status:'idle', generation:0, controller:null, url:null, blob:null, cache:new Map(), page:1, selection:null, font:Number(stored('font',20)), bookRequest:0, blogPage:1, postRequest:0, jobs:[], speeds:{}, cloud:false, jobTimer:null, voices:[], queue:[], playlists:[], playlist:null, action:null, serverReady:new Set(), cacheCheck:0, coverBust:{}, liveSpeed:{} };
const coverUrl=(doc,kind='documents')=>doc.cover==='own'?`./api/${kind}/${doc.id}/cover${state.coverBust[doc.id]?'?v='+state.coverBust[doc.id]:''}`:doc.cover&&/^https:/.test(doc.cover)?doc.cover:null;
const audio = $('audio'); let toastTimer, progressTimer;
async function api(route, options={}) {
  const response = await fetch('./api/'+route,{...options,headers:{...(options.body && !(options.body instanceof Blob)?{'Content-Type':'application/json'}:{}),...options.headers}});
  if(!response.ok){const data=await response.json().catch(()=>({}));const e=new Error(data.error || 'Não foi possível concluir o pedido.');e.status=response.status;if(response.status===401 && state.user){state.user=null;updateAccount();}throw e;}
  return response.headers.get('content-type')?.includes('audio/')?response.blob():response.json();
}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,6000);}
async function busy(message, action){$('busy-message').textContent=message;$('busy-overlay').hidden=false;try{return await action();}catch(e){toast(e.message);}finally{$('busy-overlay').hidden=true;}}
function login(){if(!$('login-dialog').open)$('login-dialog').showModal();}
function requireUser(){if(state.user)return true;login();return false;}
function updateAccount(){$('account').textContent=state.user?state.user.username+' · Sair':'Entrar no Kavita';}
// The view (and open document) lives in the URL hash, so a refresh or the back button lands where you were.
function changeView(name){setTimeout(keepAwake,0);const hash='#'+name+(name==='reader'&&state.doc?'/'+state.doc.id:'');if(location.hash!==hash)history.pushState(null,'',hash);document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==name+'-view');document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('view-label').textContent=({home:'Visão geral',kavita:'Biblioteca Kavita',blogs:'Blogues',shelf:'A minha estante',queue:'Fila',playlists:'Playlists',audio:'Áudios',write:'Escrever texto',settings:'Definições',reader:'Leitura'})[name];document.body.classList.remove('menu-open');$('menu-toggle').setAttribute('aria-expanded','false');window.scrollTo({top:0,behavior:'instant'});if(name==='kavita'&&state.user&&!$('library-select').value)loadLibraries();if(name==='shelf')refreshShelf();if(name==='blogs'&&!$('blog-select').value)loadBlogs();if(name==='audio')refreshJobs();if(name==='settings')renderSettings();if(name==='queue')renderQueue();if(name==='playlists')renderPlaylists();}
function applyAppearance(){applyAppearanceBase();applyReadColors();styleBook();}
function applyAppearanceBase(){document.documentElement.dataset.theme=stored('theme',matchMedia('(prefers-color-scheme: light)').matches?'light':'dark');// Two designs: Livro (everything) and Foco (only the text in the reader, no decoration elsewhere); the old 'clean' is Livro.
  const mode=stored('mode','standard')==='reading'?'reading':'standard';document.body.classList.toggle('mode-clean',mode==='reading');document.body.classList.toggle('mode-reading',mode==='reading');$('book-ui').setAttribute('aria-pressed',mode!=='reading');$('reading-mode').setAttribute('aria-pressed',mode==='reading');$('theme-toggle').setAttribute('aria-label',document.documentElement.dataset.theme==='dark'?'Ativar tema claro':'Ativar tema escuro');document.documentElement.style.setProperty('--reading-font',Math.min(30,Math.max(16,state.font))+'px');for(const [key,cls] of [['uiReady','no-ready'],['uiLocal','no-local'],['uiStripes','no-stripes'],['uiEta','no-eta'],['uiWord','no-word'],['uiChapters','no-chapters']])document.body.classList.toggle(cls,stored(key,'1')!=='1');document.body.dataset.contrast=stored('uiContrast','normal');}
applyAppearance();
$('theme-toggle').onclick=()=>{store('theme',document.documentElement.dataset.theme==='dark'?'light':'dark');applyAppearance();};
$('book-ui').onclick=()=>{store('mode','standard');applyAppearance();};$('reading-mode').onclick=()=>{store('mode','reading');applyAppearance();};
$('menu-toggle').onclick=()=>{document.body.classList.toggle('menu-open');$('menu-toggle').setAttribute('aria-expanded',document.body.classList.contains('menu-open'));};document.querySelector('.main-shell').addEventListener('click',e=>{if(document.body.classList.contains('menu-open')&&!e.target.closest('#menu-toggle')){e.preventDefault();e.stopPropagation();document.body.classList.remove('menu-open');$('menu-toggle').setAttribute('aria-expanded','false');}},true);
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>changeView(b.dataset.view));
for(const id of ['open-library','source-kavita'])$(id).onclick=()=>{changeView('kavita');if(!state.user)login();};
for(const id of ['open-write','source-write'])$(id).onclick=()=>changeView('write');$('source-blogs').onclick=()=>changeView('blogs');
$('all-documents').onclick=$('reader-back').onclick=()=>changeView('shelf');$('now-playing').onclick=()=>{if(state.doc)changeView('reader');};$('now-playing').title='Abrir a leitura';
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
$('account').onclick=async()=>{if(!state.user)return login();stop();await api('logout',{method:'POST'});state.user=null;state.docs=[];state.doc=null;state.jobs=[];state.queue=[];state.playlists=[];state.playlist=null;$('player').hidden=true;renderDocuments();renderJobs();renderQueue();renderPlaylists();blogPlaceholder('Entra no Kavita para ver os blogues');$('post-grid').replaceChildren();updateAccount();changeView('home');toast('Sessão terminada.');};
$('login-form').onsubmit=async event=>{event.preventDefault();$('login-error').textContent='';const button=event.currentTarget.querySelector('button[type=submit]');button.disabled=true;try{const apiKey=$('api-key').value.trim();state.user=await api('login',{method:'POST',body:JSON.stringify(apiKey?{apiKey}:{username:$('username').value.trim(),password:$('password').value})});$('password').value='';$('api-key').value='';$('login-dialog').close();updateAccount();await pullSettings();await Promise.all([refreshShelf(),loadVoices(),loadLibraries(),loadLists()]);if(!$('audio-view').hidden)refreshJobs();if(!$('blog-select').value)loadBlogs();renderQueue();renderPlaylists();updateUpNext();toast('Bem-vindo, '+state.user.username+'.');if(location.hash.startsWith('#reader/'))applyHash();}catch(e){$('login-error').textContent=e.message;}finally{button.disabled=false;}};
async function refreshShelf(){if(!state.user){state.docs=[];renderDocuments();return;}try{state.docs=await api('documents');renderDocuments();loadKavitaReading();}catch(e){toast(e.message);}}
function documentCard(doc, kind='shelf'){const card=document.createElement('div');card.className='document-card';const button=document.createElement('button');button.className='document-open';const cover=document.createElement('div');cover.className='document-cover';const small=document.createElement('small');small.textContent=kind==='kavita'?'KAVITA':kind==='blog'?'BLOGUE':doc.source||'DOCUMENTO';const title=document.createElement('span');title.textContent=String(doc.title||doc.name||'Sem título');title.className='cover-title';const symbol=document.createElement('span');symbol.className='cover-symbol';symbol.textContent=kind==='blog'?'✦':'▤';const imageUrl=kind==='kavita'?'./api/cover?series='+encodeURIComponent(doc.id):kind==='blog'?doc.image:coverUrl(doc);if(imageUrl){const image=document.createElement('img');image.className='cover-image';image.loading='lazy';image.alt='';image.referrerPolicy='no-referrer';image.src=imageUrl;image.onerror=()=>image.remove();cover.append(image);}cover.append(small,title,symbol);const body=document.createElement('div');body.className='document-body';button.title=doc.title||doc.name||'';const caption=document.createElement('p');const ready=kind==='shelf'?audioJobs(doc.id):[];if(ready.length){card.classList.add('has-audio');const badge=document.createElement('span');badge.className='audio-badge';badge.textContent='♫ Áudio pronto · '+ready.map(j=>j.voiceName.split(' · ')[0]).filter((v,i,a)=>a.indexOf(v)===i).join(', ');body.append(badge);}if(doc.auto){const auto=document.createElement('span');auto.className='audio-badge';auto.textContent='⟳ Áudio automático';body.append(auto);}const percent=kind==='shelf'?(doc.progress?.read?100:doc.progress?.percent||0):0;if(kind==='shelf'&&doc.progress?.read){const done=document.createElement('span');done.className='audio-badge read-badge';done.textContent='✓ Lido';body.append(done);}caption.textContent=kind==='kavita'?'Escolher livro e ouvir →':kind==='blog'?`${doc.published.slice(0,10)} · ${Math.max(1,Math.round(doc.chars/1000))} mil caracteres · Ler e ouvir →`:`${doc.sections} ${doc.sections===1?'secção':'secções'} · ${percent>=100?'Concluído · Ouvir de novo →':percent>0?percent+'% · Continuar →':ready.length?'Tocar →':'Ler e ouvir →'}`;body.append(caption);if(percent>0){const bar=document.createElement('div');bar.className='card-progress';const fill=document.createElement('span');fill.style.width=percent+'%';bar.append(fill);button.append(cover,bar);}if(!percent)button.append(cover);button.append(body);button.onclick=()=>kind==='kavita'?chooseBook(doc):kind==='blog'?importPost(doc):openSaved(doc.id);card.append(button);const menu=document.createElement('button');menu.className='card-menu';menu.textContent='⋯';menu.setAttribute('aria-label','Opções de '+(doc.title||doc.name));menu.onclick=e=>{e.stopPropagation();itemMenu(doc,kind);};card.append(menu);return card;}
// Re-import from where the document came from (Kavita chapter or blog post); the id and reading position are kept.
async function updateDoc(doc){const o=doc.origin;if(!o)return;const wasOpen=state.doc?.id===doc.id;await busy('A atualizar a partir da origem…',async()=>{const fresh=o.kind==='kavita'?await api('import-book',{method:'POST',body:JSON.stringify({chapter:o.chapter,series:o.series,title:doc.title})}):await api('import-post',{method:'POST',body:JSON.stringify({blog:o.blog,post:o.post})});await refreshShelf();toast('Atualizado: '+fresh.sections.length+(fresh.sections.length===1?' secção.':' secções.'));if(wasOpen)await openDoc(fresh);});}
async function checkNewer(doc){$('reader-update').hidden=true;if(doc.origin?.kind!=='kavita'||!doc.origin.series)return;try{const chapters=await api('chapters?series='+doc.origin.series);const chapter=chapters.find(c=>c.id===doc.origin.chapter);if(chapter?.modified&&Date.parse(chapter.modified)>Date.parse(doc.updated)&&state.doc?.id===doc.id)$('reader-update').hidden=false;}catch{}}
$('reader-update').onclick=()=>{if(state.doc)updateDoc(state.doc);};
async function removeDoc(doc){if(!confirm('Remover “'+doc.title+'” da tua estante?'))return;try{await api('documents/'+doc.id,{method:'DELETE'});if(state.doc?.id===doc.id){stop();state.doc=null;$('player').hidden=true;changeView('shelf');}await refreshShelf();}catch(e){toast(e.message);}}
function empty(target,message){const item=document.createElement('div');item.className='empty-state';item.textContent=message;target.append(item);}
// "A ler no Kavita": started in Kavita, not on the shelf; opening imports it and lands on Kavita's position.
async function loadKavitaReading(){const block=$('kavita-reading-block');if(!state.user){block.hidden=true;return;}let list=[];try{list=await api('kavita/reading');}catch{}const target=$('kavita-reading');target.replaceChildren();block.hidden=!list.length;for(const b of list){const card=documentCard({id:b.series,title:b.title,name:b.title},'kavita');const caption=card.querySelector('.document-body p, .document-body .card-caption')||card.querySelector('.document-body').lastElementChild;if(caption)caption.textContent=(b.percent?b.percent+'% no Kavita · ':'')+'Continuar aqui →';if(b.percent){const bar=document.createElement('div');bar.className='card-progress';const fill=document.createElement('span');fill.style.width=b.percent+'%';bar.append(fill);card.querySelector('.document-cover').after(bar);}card.querySelector('.document-open').onclick=()=>importBook({id:b.chapter,title:'Livro'},{id:b.series,name:b.title});card.querySelector('.card-menu')?.remove();target.append(card);}}
function renderDocuments(){const query=$('shelf-search').value.trim().toLowerCase();const recent=[...state.docs].sort((a,b)=>(b.progress?.at||b.updated).localeCompare(a.progress?.at||a.updated)).slice(0,4);const shelf=query?state.docs.filter(d=>(d.title+' '+d.source).toLowerCase().includes(query)):state.docs;for(const[id,docs]of[['recent-documents',recent],['shelf-documents',shelf]]){const target=$(id);target.replaceChildren();docs.forEach(d=>target.append(documentCard(d)));if(!state.docs.length)empty(target,state.user?'A tua estante está pronta para a primeira leitura.':'Entra no Kavita para guardar documentos e continuar as tuas leituras.');else if(!docs.length)empty(target,'Nada na estante corresponde a “'+$('shelf-search').value.trim()+'”.');}}
$('shelf-search').oninput=renderDocuments;
async function loadLibraries(){try{const libraries=await api('libraries');$('library-select').replaceChildren();for(const lib of libraries){const option=document.createElement('option');option.value=lib.id;option.textContent=lib.name;$('library-select').append(option);}if(!libraries.length){empty($('book-grid'),'Não há bibliotecas disponíveis nesta conta.');return;}state.page=1;await loadBooks();}catch(e){toast(e.message);}}
async function loadBooks(){if(!requireUser()||!$('library-select').value)return;const generation=++state.bookRequest;const target=$('book-grid');target.replaceChildren();empty(target,'A procurar na tua biblioteca…');try{const data=await api(`books?library=${encodeURIComponent($('library-select').value)}&page=${state.page}&q=${encodeURIComponent($('book-search').value)}`);if(generation!==state.bookRequest)return;target.replaceChildren();for(const book of data.books)target.append(documentCard(book,'kavita'));if(!data.books.length)empty(target,'Não foram encontrados livros.');let pages=0;try{pages=JSON.parse(data.pagination||'{}').totalPages||0;}catch{}$('page-label').textContent='Página '+state.page+(pages?' de '+pages:'');$('previous-page').disabled=state.page===1;$('next-page').disabled=pages?state.page>=pages:data.books.length<48;}catch(e){if(generation!==state.bookRequest)return;target.replaceChildren();empty(target,e.message);}}
$('library-select').onchange=()=>{state.page=1;loadBooks();};$('search-books').onclick=()=>{state.page=1;loadBooks();};$('book-search').onkeydown=e=>{if(e.key==='Enter')$('search-books').click();};$('book-search').addEventListener('search',()=>$('search-books').click());$('previous-page').onclick=()=>{if(state.page>1){state.page--;loadBooks();}};$('next-page').onclick=()=>{state.page++;loadBooks();};
function blogPlaceholder(text){const option=document.createElement('option');option.value='';option.textContent=text;$('blog-select').replaceChildren(option);}
async function loadBlogs(){if(!state.user){blogPlaceholder('Entra no Kavita para ver os blogues');$('post-grid').replaceChildren();empty($('post-grid'),'Os blogues ficam disponíveis depois de entrares.');login();return;}blogPlaceholder('A carregar blogues…');try{const blogs=await api('blogs');$('blog-select').replaceChildren();for(const blog of blogs){const option=document.createElement('option');option.value=blog.index;option.textContent=blog.title;$('blog-select').append(option);}if(!blogs.length){empty($('post-grid'),'Não há blogues configurados neste servidor.');return;}state.blogPage=1;await loadPosts();}catch(e){blogPlaceholder(e.status===401?'Entra no Kavita para ver os blogues':'Sem ligação aos blogues');$('post-grid').replaceChildren();empty($('post-grid'),e.message);if(e.status===401)login();}}
async function loadPosts(){if($('blog-select').value==='')return;const generation=++state.postRequest;const target=$('post-grid');target.replaceChildren();empty(target,'A procurar artigos…');try{const data=await api(`blog-posts?blog=${encodeURIComponent($('blog-select').value)}&page=${state.blogPage}`);if(generation!==state.postRequest)return;target.replaceChildren();for(const post of data.posts)target.append(documentCard(post,'blog'));if(!data.posts.length)empty(target,'Este blogue ainda não tem artigos publicados.');$('posts-label').textContent='Página '+state.blogPage+' · '+data.total+' artigos';$('previous-posts').disabled=state.blogPage===1;$('next-posts').disabled=state.blogPage*24>=data.total;}catch(e){if(generation!==state.postRequest)return;target.replaceChildren();empty(target,e.message);}}
$('blog-select').onchange=()=>{state.blogPage=1;loadPosts();};$('previous-posts').onclick=()=>{if(state.blogPage>1){state.blogPage--;loadPosts();}};$('next-posts').onclick=()=>{state.blogPage++;loadPosts();};
async function importPost(post,action=null){if(!requireUser())return;if(!action)stop();await busy('A preparar o artigo…',async()=>{const doc=await api('import-post',{method:'POST',body:JSON.stringify({blog:Number($('blog-select').value),post:post.id})});await refreshShelf();if(action)await runAction(action,doc);else await openDoc(doc);});}
async function chooseBook(book){await busy('A abrir os livros desta série…',async()=>{const chapters=await api('chapters?series='+book.id);$('book-title').textContent=book.name;$('book-chapters').replaceChildren();if(!chapters.length)empty($('book-chapters'),'Esta série não tem livros disponíveis.');for(const chapter of chapters){const button=document.createElement('button');button.className='chapter-choice';button.textContent=(chapter.title==='Livro'?book.name:chapter.title)+' · '+chapter.pages+' páginas';button.onclick=()=>importBook(chapter,book,state.action);$('book-chapters').append(button);}$('chapters-dialog').showModal();});}
$('chapters-dialog').onclose=()=>{state.action=null;};
async function importBook(chapter,book,action=null){$('chapters-dialog').close();state.action=null;if(!action)stop();await busy('A preparar o texto do livro…',async()=>{const doc=await api('import-book',{method:'POST',body:JSON.stringify({chapter:chapter.id,series:book.id,title:chapter.title==='Livro'?book.name:chapter.title})});await refreshShelf();if(action)await runAction(action,doc);else await openDoc(doc);});}
function uploadFile(file){if(!file||!requireUser())return;if(file.size>50*1024*1024)return toast('O limite por documento é 50 MB.');stop();busy('A abrir '+file.name+'…',async()=>{const doc=await api('upload?name='+encodeURIComponent(file.name),{method:'POST',body:file,headers:{'Content-Type':'application/octet-stream'}});await refreshShelf();await openDoc(doc);});}
$('file-input').onchange=event=>{uploadFile(event.target.files[0]);event.target.value='';};$('drop-zone').onclick=$('upload-shelf').onclick=()=>{if(requireUser())$('file-input').click();};$('drop-zone').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('drop-zone').click();}};for(const event of ['dragenter','dragover'])$('drop-zone').addEventListener(event,e=>{e.preventDefault();$('drop-zone').classList.add('dragging');});for(const event of ['dragleave','drop'])$('drop-zone').addEventListener(event,e=>{e.preventDefault();$('drop-zone').classList.remove('dragging');if(event==='drop')uploadFile(e.dataTransfer.files[0]);});window.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault();});window.addEventListener('drop',e=>{if(e.dataTransfer.files.length){e.preventDefault();if(!e.target.closest('#drop-zone'))uploadFile(e.dataTransfer.files[0]);}});
$('text-input').value=stored('draft','');$('text-title').value=stored('draft-title','');function countText(){$('character-count').textContent=$('text-input').value.length.toLocaleString('pt-PT')+' caracteres';store('draft',$('text-input').value);store('draft-title',$('text-title').value);}$('text-input').oninput=$('text-title').oninput=countText;countText();
$('text-form').onsubmit=event=>{event.preventDefault();if(!requireUser())return;busy('A guardar as tuas palavras…',async()=>{const doc=await api('documents',{method:'POST',body:JSON.stringify({title:$('text-title').value.trim()||'As minhas palavras',source:'Texto escrito',sections:[{title:'Texto',text:$('text-input').value}]})});await refreshShelf();await openDoc(doc);});};
async function openSaved(id,options){await busy('A abrir a tua leitura…',async()=>openDoc(await api('documents/'+id),options));}
async function openDoc(doc,{keepVoice=false}={}){saveProgress(true);stop();state.doc=doc;sectionChunks.clear();state.cache.clear();let progress={section:0,position:0};try{progress=await api('documents/'+doc.id+'/progress');}catch{}state.section=Math.min(progress.section||0,doc.sections.length-1);renderChapters();renderSection(progress.position||0);$('reader-title').textContent=$('reader-title-side').textContent=doc.title;$('reader-source').textContent=doc.source;$('now-playing').textContent=doc.title;$('player').hidden=false;changeView('reader');checkNewer(doc);offerPriority(doc);if(!state.hlLoaded){state.hlLoaded=true;loadHighlightColors();}loadNotes();if(!$('voice').options[0]?.value)await loadVoices();if(!keepVoice&&applyPreferredVoice(doc))checkServerCache();else if(!state.serverReady.size&&!state.cacheCheck)checkServerCache();setStatus('idle');if(progress.position)requestAnimationFrame(()=>document.querySelector('#reader-text p.active')?.scrollIntoView({block:'center'}));}
function renderChapters(){$('toc-title').textContent=state.doc.title;for(const target of [$('chapter-list'),$('toc-list')]){target.replaceChildren();state.doc.sections.forEach((section,index)=>{const button=document.createElement('button');button.textContent=String(index+1).padStart(2,'0')+' · '+section.title;button.className=index===state.section?'active':'';button.onclick=()=>{$('toc-dialog').close();changeSection(index);};target.append(button);});}}
$('toc-button').onclick=$('section-count').onclick=()=>{if(!state.doc)return;$('toc-dialog').showModal();$('toc-list .active')?.scrollIntoView?.({block:'center'});};
function totalChars(){return state.chunks.reduce((sum,c)=>sum+c.length,0)||1;}
function startChars(index){return state.chunks.slice(0,index).reduce((sum,c)=>sum+c.length,0);}
