{const slider=$('volume-slider');const fromEvent=e=>{const rect=slider.getBoundingClientRect();return (1-(e.clientY-rect.top)/rect.height)*100;};slider.onpointerdown=e=>{slider.setPointerCapture(e.pointerId);setVolume(fromEvent(e));slider.onpointermove=ev=>setVolume(fromEvent(ev));};slider.onpointerup=slider.onpointercancel=()=>{slider.onpointermove=null;};slider.onkeydown=e=>{const step={ArrowUp:5,ArrowRight:5,ArrowDown:-5,ArrowLeft:-5}[e.key];if(step!==undefined){e.preventDefault();setVolume(Number($('volume').value)+step);}};}$('volume-button').onclick=()=>{const open=$('volume-panel').hidden;$('volume-panel').hidden=!open;$('volume-button').setAttribute('aria-expanded',String(open));};document.addEventListener('pointerdown',e=>{if(!$('volume-panel').hidden&&!e.target.closest('.volume-pop')){$('volume-panel').hidden=true;$('volume-button').setAttribute('aria-expanded','false');}});$('speed').value=stored('speed','1');if(!$('speed').value)$('speed').value='1';function showSpeed(){$('speed-value').textContent=Number($('speed').value).toLocaleString('pt-PT',{maximumFractionDigits:2})+'×';$('speed-down').disabled=$('speed').selectedIndex===0;$('speed-up').disabled=$('speed').selectedIndex===$('speed').options.length-1;}showSpeed();
