document.querySelectorAll('#item-dialog [data-action]').forEach(b=>b.onclick=async()=>{$('item-dialog').close();const {doc,kind}=state.menuTarget,action=b.dataset.action;if(action==='open'){kind==='kavita'?chooseBook(doc):kind==='blog'?importPost(doc):openSaved(doc.id);return;}if(action==='cover'){if(await pickCover('documents',doc.id))await refreshShelf();return;}if(action==='remove')return removeDoc(doc);if(action==='update')return updateDoc(doc);if(action==='word'){const link=document.createElement('a');link.href='./api/documents/'+doc.id+'/export.docx';link.download='';document.body.append(link);link.click();link.remove();toast('A preparar o ficheiro Word…');return;}if(action==='auto')return toggleAuto(doc);if(kind==='kavita'){state.action=action;await chooseBook(doc);return;}if(kind==='blog')return importPost(doc,action);await runAction(action,doc);});
async function runAction(action,doc){if(action==='next'){state.queue=[doc.id,...state.queue.filter(id=>id!==doc.id)];await saveQueue();toast('“'+doc.title+'” toca a seguir.');}else if(action==='queue'){if(!state.queue.includes(doc.id))state.queue.push(doc.id);await saveQueue();toast('Adicionado à fila.');}else if(action==='playlist')pickPlaylist(doc.id);}
