function duration(seconds){seconds=Math.max(0,Math.round(seconds));if(seconds<60)return seconds+' s';const h=Math.floor(seconds/3600),m=Math.round(seconds%3600/60);return h?`${h} h ${String(m).padStart(2,'0')} min`:`${m} min`;}
function liveSpeed(voice){return state.liveSpeed[voice]||jobSpeed(voice);}
function jobSpeed(voice){return state.speeds[voice]||(voice.startsWith('sopro_')?10:voice==='kokoro_eu_pt'?20:voice.startsWith('pt_PT-')||voice.startsWith('phoonnx_')?100:50);}
