// "Edição do livro": the author's EPUB pages in a script-less, same-origin frame. The plain passages stay in the DOM
// (hidden) and keep driving playback; their state classes are mirrored onto the matching blocks of the edition.
const BOOK_BLOCKS='p,h1,h2,h3,h4,h5,h6,li,blockquote,pre,figcaption,dt,dd,td,th';
