  state.bookMap=map;paintNotes();bookNoteEvents(d);d.body.addEventListener('click',e=>{const b=e.target.closest?.('[data-lec]');if(b&&d.getSelection()?.isCollapsed!==false){e.preventDefault();seek(Number(b.dataset.lec),0);}});
  const fit=()=>{if(state.bookPaged)return;frame.style.height=d.documentElement.scrollHeight+'px';};fit();new ResizeObserver(fit).observe(d.body);d.fonts?.ready.then(()=>{fit();layoutPages();});const end=d.createElement('span');end.id='lec-end';d.body.append(end);pageInput(d);state.bookPage=state.bookStartLast?1e9:0;state.bookStartLast=false;layoutPages();mirrorBook();
