// The "Aa" panel: view, size, page colour and contrast in one place, each choice visibly pressed.
function syncLook(){const view=!state.doc?.book?'plain':stored('bookMode','1')!=='1'?'plain':stored('bookPages','0')==='1'?'pages':'book';$('look-mode-row').hidden=!state.doc?.book;for(const b of document.querySelectorAll('#look-mode button'))b.setAttribute('aria-pressed',b.dataset.mode===view);const inBook=view!=='plain',colors=inBook&&stored('bookColors','book')!=='mine'?'app':stored('readColors','app');for(const b of document.querySelectorAll('#look-colors button'))b.setAttribute('aria-pressed',b.dataset.colors===colors);document.querySelector('#look-colors .swatch-app span').textContent=inBook?'Do livro':'Tema';for(const b of document.querySelectorAll('#look-contrast button'))b.setAttribute('aria-pressed',b.dataset.contrast===stored('readContrast','normal'));$('font-value').textContent=Math.round(state.font/20*100)+'%';$('look-hint').textContent=view==='pages'?'Arrasta a página a partir da borda, toca nas margens ou usa as setas para folhear.':view==='book'?'A edição mostra o livro com o estilo do autor.':'';}
