async function loadNotes(){const doc=state.doc;state.notes=[];state.notesError=null;notesBadge();if(!doc?.id||!state.user)return;try{const list=await api('documents/'+doc.id+'/notes');if(state.doc!==doc)return;state.notes=list;}catch(e){if(state.doc===doc)state.notesError=e.message;}sortNotes();notesBadge();paintNotes();if(!$('notes-dialog').hidden&&$('notes-dialog').open)renderNotes();}
