function notesBadge(){const n=state.notes.length;$('notes-count').textContent=n>99?'99+':n;$('notes-count').hidden=!n;}
function textIndex(root){const nodes=[];let text='';const w=root.ownerDocument.createTreeWalker(root,NodeFilter.SHOW_TEXT);for(let n;(n=w.nextNode());){nodes.push({n,at:text.length});text+=n.data;}return {text,nodes};}
