function captureBookSelection(d){const sel=d.getSelection();if(!sel||sel.isCollapsed||!sel.toString().trim())return;const range=sel.getRangeAt(0);const node=range.startContainer.nodeType===1?range.startContainer:range.startContainer.parentElement;const block=node?.closest?.('[data-lec]');if(!block)return;const k=Number(block.dataset.lec),text=sel.toString(),re=quoteRe(text.trim().split(/\s+/).slice(0,8).join(' '));let index=k,offset=0;for(let j=k;j<state.chunks.length&&state.bookMap[j]===block;j++){re.lastIndex=0;const m=re.exec(state.chunks[j]);if(m){index=j;offset=m.index;break;}}state.selection={index,offset,text};$('selection-bar').hidden=false;}
function clearSelection(){window.getSelection()?.removeAllRanges();try{$('book-frame').contentDocument?.getSelection()?.removeAllRanges();}catch{}state.selection=null;$('selection-bar').hidden=true;}
function selectionPlace(){const s=state.selection;return s?{section:state.section,position:startChars(s.index)+s.offset,text:String(s.text||'').replace(/\s+/g,' ').trim().slice(0,2000)}:{section:state.section,position:Math.max(0,Math.floor(state.position)),text:''};}
const inKavita=()=>state.doc?.origin?.kind==='kavita'&&state.doc.sections.some(s=>Number.isInteger(s.page));
async function createNote(n){if(!requireUser()||!state.doc)return null;const doc=state.doc;try{const saved=await api('documents/'+doc.id+'/notes',{method:'POST',body:JSON.stringify(n)});if(state.doc!==doc)return saved;state.notes.push(saved);sortNotes();notesBadge();paintNotes();if($('notes-dialog').open)renderNotes();toast((n.kind==='bookmark'?'Marcador guardado':n.comment?'Nota guardada':'Destaque guardado')+(inKavita()?' — também no Kavita.':'.'));return saved;}catch(e){toast(e.message);return null;}}
for(const b of document.querySelectorAll('#selection-bar .sel-color'))b.onclick=()=>{const place=selectionPlace();clearSelection();if(place.text){store('noteColor',b.dataset.color);createNote({kind:'note',...place,comment:'',color:Number(b.dataset.color)});}};
$('selection-note').onclick=()=>{const place=selectionPlace();clearSelection();if(place.text)openNote({kind:'note',...place,comment:'',color:Number(stored('noteColor','0'))||0,mine:true},true);};
$('selection-mark').onclick=()=>{const place=selectionPlace();clearSelection();createNote({kind:'bookmark',...place,comment:''});};
$('selection-close').onclick=clearSelection;
$('bookmark-button').onclick=()=>{if(!state.doc)return;const place=selectionPlace();clearSelection();createNote({kind:'bookmark',...place,text:place.text,comment:''});};
document.addEventListener('keydown',e=>{if((e.key==='m'||e.key==='M')&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!$('reader-view').hidden&&!e.target.closest?.('input,textarea,select,[contenteditable]')&&!document.querySelector('dialog[open]')){e.preventDefault();$('bookmark-button').click();}});
// The note editor: new notes from a selection, or an existing one (only your own can be changed).
let editing=null;
function openNote(n,isNew=false){editing={...n,isNew};const own=isNew||n.mine!==false;$('note-kind').textContent=n.kind==='bookmark'?'MARCADOR':isNew?'NOVA NOTA':'NOTA';$('note-quote').textContent=n.text||(state.doc.sections[n.section]?.title||'');$('note-quote').hidden=!n.text&&n.kind!=='bookmark';$('note-colors').hidden=n.kind==='bookmark';$('note-label').textContent=n.kind==='bookmark'?'Nome':'Comentário';$('note-text').value=n.comment||'';$('note-text').readOnly=!own||(n.kind==='bookmark'&&!isNew&&inKavita());setNoteColor(n.color||0);$('note-meta').textContent=[state.doc.sections[n.section]?.title,n.owner&&!n.mine?'de '+n.owner:'',inKavita()?'guardada no Kavita':''].filter(Boolean).join(' · ');$('note-delete').hidden=isNew||!own;$('note-go').hidden=isNew;$('note-save').hidden=!own||(n.kind==='bookmark'&&!isNew);if(!$('note-dialog').open)$('note-dialog').showModal();if(own&&!$('note-text').readOnly)setTimeout(()=>$('note-text').focus(),50);}
function setNoteColor(c){if(editing)editing.color=c;for(const b of document.querySelectorAll('#note-colors .sel-color'))b.setAttribute('aria-checked',String(Number(b.dataset.color)===c));}
for(const b of document.querySelectorAll('#note-colors .sel-color'))b.onclick=()=>{if(editing?.mine!==false)setNoteColor(Number(b.dataset.color));};
$('note-save').onclick=async()=>{const n=editing;if(!n)return;const comment=$('note-text').value.trim();if(n.isNew){$('note-dialog').close();store('noteColor',String(n.color||0));await createNote({kind:n.kind,section:n.section,position:n.position,text:n.text,comment,color:n.color||0});return;}try{await api('documents/'+state.doc.id+'/notes/'+n.id,{method:'PUT',body:JSON.stringify({comment,color:n.color||0})});const local=state.notes.find(x=>x.id===n.id);if(local){local.comment=comment;local.color=n.color||0;}paintNotes();if($('notes-dialog').open)renderNotes();$('note-dialog').close();toast('Nota atualizada'+(inKavita()?' — também no Kavita.':'.'));}catch(e){toast(e.message);}};
$('note-delete').onclick=async()=>{const n=editing;if(!n||!confirm(n.kind==='bookmark'?'Apagar este marcador?':'Apagar esta nota?'))return;try{await api('documents/'+state.doc.id+'/notes/'+n.id,{method:'DELETE'});state.notes=state.notes.filter(x=>x.id!==n.id);notesBadge();paintNotes();if($('notes-dialog').open)renderNotes();$('note-dialog').close();toast('Apagado'+(inKavita()?' — também no Kavita.':'.'));}catch(e){toast(e.message);}};
$('note-go').onclick=()=>{const n=editing;$('note-dialog').close();$('notes-dialog').open&&$('notes-dialog').close();if(n)goTo(n.section,n.position);};
// Go to a place in the document, keeping playback going when it was playing.
function goTo(section,position){if(!state.doc||!state.doc.sections[section])return;const playing=['playing','loading'].includes(state.status);if(state.status!=='idle'){stop();setStatus('idle');}if(section!==state.section){saveProgress(true);state.section=section;sectionChunks.delete(section);renderChapters();}renderSection(position);saveProgress(true);if(playing)seek(state.index,state.offset,true);requestAnimationFrame(()=>document.querySelector('#reader-text p.active')?.scrollIntoView({block:'center'}));}
// The list: grouped by chapter, filterable, copyable as Markdown.
function renderNotes(){const list=$('notes-list');list.replaceChildren();$('notes-origin').textContent=inKavita()?'Guardados no Kavita: aparecem também no leitor do Kavita.':'Guardados nesta conta do Lectoria.';for(const b of document.querySelectorAll('#notes-filter button'))b.setAttribute('aria-pressed',String(b.dataset.filter===state.noteFilter));if(state.notesError){empty(list,state.notesError);return;}const shown=state.notes.filter(n=>state.noteFilter==='all'||n.kind===state.noteFilter);if(!shown.length){empty(list,state.notes.length?'Nada neste filtro.':'Ainda não há marcadores nem notas. Seleciona texto para destacar ou anotar, ou usa o botão de marcador.');return;}let last=-1;for(const n of shown){if(n.section!==last){last=n.section;const h=document.createElement('h3');h.className='notes-chapter';h.textContent=state.doc.sections[n.section]?.title||'Capítulo '+(n.section+1);list.append(h);}const item=document.createElement('div');item.className='note-item '+n.kind;item.style.setProperty('--note',n.kind==='bookmark'?'var(--accent)':NOTE_COLORS[n.color||0]);const go=document.createElement('button');go.type='button';go.className='note-body';const kind=document.createElement('span');kind.className='note-tag';kind.textContent=n.kind==='bookmark'?'Marcador':n.comment?'Nota':'Destaque';go.append(kind);if(n.text){const q=document.createElement('q');q.textContent=n.text.length>220?n.text.slice(0,220)+'…':n.text;go.append(q);}if(n.comment){const c=document.createElement('span');c.className='note-comment';c.textContent=n.comment;go.append(c);}if(n.owner&&!n.mine){const o=document.createElement('span');o.className='note-owner';o.textContent='de '+n.owner;go.append(o);}go.onclick=()=>{$('notes-dialog').close();goTo(n.section,n.position);};const edit=document.createElement('button');edit.type='button';edit.className='icon-button note-edit';edit.setAttribute('aria-label','Abrir');edit.innerHTML='<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/></svg>';edit.onclick=()=>openNote(n);item.append(go,edit);list.append(item);}}
$('notes-button').onclick=()=>{if(!state.doc)return;$('export-share').querySelector('span').textContent='Enviar por email…';renderNotes();$('notes-dialog').showModal();if(!state.notes.length&&!state.notesError)loadNotes();};
for(const b of document.querySelectorAll('#notes-filter button'))b.onclick=()=>{state.noteFilter=b.dataset.filter;renderNotes();};
$('notes-copy').onclick=async()=>{const lines=['# '+state.doc.title,''];let last=-1;for(const n of state.notes){if(n.section!==last){last=n.section;lines.push('## '+(state.doc.sections[n.section]?.title||''),'');}lines.push(n.kind==='bookmark'?'- 🔖 '+(n.comment||n.text):'> '+n.text+(n.comment?'\n\n'+n.comment:''),'');}try{await navigator.clipboard.writeText(lines.join('\n'));toast('Copiado em Markdown.');}catch{toast('Não foi possível copiar.');}};

// Word export of the open document with its bookmarks and notes: download, share (email app on phones/Windows), or save on the server.
async function exportBlob(){const r=await fetch('./api/documents/'+state.doc.id+'/export.docx');if(!r.ok)throw new Error((await r.json().catch(()=>({}))).error||'Não foi possível criar o ficheiro Word.');const name=decodeURIComponent((r.headers.get('content-disposition')||'').match(/filename\*=UTF-8''([^;]+)/)?.[1]||'Lectoria.docx');return new File([await r.blob()],name,{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'});}
function saveFile(file){const a=document.createElement('a');a.href=URL.createObjectURL(file);a.download=file.name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),5000);}
$('export-download').onclick=()=>{if(state.doc)busy('A criar o ficheiro Word…',async()=>{saveFile(await exportBlob());toast('Ficheiro Word descarregado.');});};
$('export-save').onclick=()=>{if(state.doc)busy('A guardar no servidor…',async()=>{const r=await api('documents/'+state.doc.id+'/export',{method:'POST',body:'{}'});toast('Guardado em '+r.saved.replace(/^\/srv\//,'').replace(/^\//,'').split('/').join(' › '));});};
// Sharing needs the tap itself: the file is prepared on the first tap; if the browser then refuses, the next tap shares it at once.
$('export-share').onclick=async()=>{if(!state.doc)return;const ready=state.exportFile&&state.exportFile.doc===state.doc.id&&Date.now()-state.exportFile.at<120000;try{const file=ready?state.exportFile.file:await busy('A criar o ficheiro Word…',exportBlob);if(!file)return;state.exportFile={file,doc:state.doc.id,at:Date.now()};if(!navigator.canShare?.({files:[file]})){saveFile(file);toast('Este browser não envia ficheiros diretamente: foi descarregado — anexa-o ao email.');return;}await navigator.share({files:[file],title:file.name.replace(/\.docx$/,''),text:'Marcadores e notas de “'+state.doc.title+'” (Lectoria).'});state.exportFile=null;}catch(e){if(e.name==='NotAllowedError'){$('export-share').querySelector('span').textContent='Enviar agora';toast('Ficheiro pronto — toca outra vez em “Enviar agora”.');}else if(e.name!=='AbortError')toast(e.message);}};

// Selections made with a pen (S Pen handles), the keyboard or a mouse all end in a selectionchange; tapping the bar keeps the selection.
let pageSelTimer;document.addEventListener('selectionchange',()=>{const sel=window.getSelection();if(sel&&!sel.isCollapsed&&!$('reader-text').contains(sel.anchorNode))return;clearTimeout(pageSelTimer);pageSelTimer=setTimeout(captureSelection,250);});
$('selection-bar').addEventListener('pointerdown',e=>e.preventDefault());

// A full audio of the open book waiting behind others: offer to put it first. Listening to the book puts it first anyway
// (live reading itself always goes before any full audio). Alone in the queue, or already next: nothing to ask.
function queueOrder(jobs){const now=Date.now(),ready=j=>Date.parse(j.startAt)<=now;return jobs.filter(j=>['queued','running'].includes(j.status)).sort((a,b)=>(b.status==='running')-(a.status==='running')||ready(b)-ready(a)||(ready(a)&&ready(b)?(b.priority||0)-(a.priority||0):0)||a.startAt.localeCompare(b.startAt)||a.created.localeCompare(b.created));}
async function offerPriority(doc){state.prioJob=null;$('prio-card').hidden=true;let data;try{data=await api('jobs');}catch{return;}if(state.doc!==doc)return;const order=queueOrder(data.jobs),mine=order.find(j=>j.doc===doc.id&&j.status==='queued');if(!mine)return;const ahead=order.indexOf(mine);if(order.length===1||ahead===0)return;state.prioJob=mine;const later=Date.parse(mine.startAt)>Date.now()?', marcado para '+new Date(mine.startAt).toLocaleString('pt-PT',{weekday:'short',hour:'2-digit',minute:'2-digit'}):'';$('prio-text').textContent=`«${doc.title}» tem um áudio completo em espera (${ahead===1?'1 áudio':ahead+' áudios'} à frente${later}). Dar-lhe prioridade?`;$('prio-yes').textContent=later?'Começar já, à frente':'Dar prioridade';$('prio-card').hidden=false;}
async function prioritise(now){const job=state.prioJob;state.prioJob=null;$('prio-card').hidden=true;if(!job)return;try{await api('jobs/'+job.id+'/priority',{method:'POST',body:JSON.stringify({now})});toast(now?'O áudio completo deste livro passou para a frente da fila. A tua leitura continua sempre primeiro.':'Estás a ouvir este livro: o áudio completo dele passou para a frente da fila.');if(!$('audio-view').hidden)refreshJobs();}catch(e){toast(e.message);}}
function promoteOnPlay(){if(state.prioJob&&state.prioJob.doc===state.doc?.id)prioritise(false);}
$('prio-yes').onclick=()=>prioritise(true);$('prio-no').onclick=()=>{$('prio-card').hidden=true;}; // ignored, it still waits: pressing play promotes it
